\section{\textbf{Research Funding}}
\vspace{0.5mm}
\begin{enumerate}[leftmargin=*, labelsep=0.5em, align=left, widest={[\textbf{S.1}]}, itemindent=0em, label={\textbf{[\arabic*]}]}]

\item[\textbf{2026}] Fieldwork support from the Dartmouth Changing Polar Regions cluster, Guarini School, Graduate Student Council, and Earth Sciences Department to drill ice cores at the Eclipse Icefield. Total grants: \$11,300.

\item[\textbf{2025}] Sub-grant from COLDEX. High-resolution CFA chemistry analysis of Allan Hills ice cores. Erich Osterberg (PI), \textbf{Jacob Chalif} (co-PI). Total grant: \$35,000.

\item[\textbf{2024}] COLDEX ECR Grant. Detailed layer analysis of oldest ice, phase 2. \textbf{Jacob Chalif} (PI). Total grant: \$5,000.

\item[\textbf{2024}] COLDEX ECR Grant. Sulfur history of MIS6/5e deglaciation. \textbf{Jacob Chalif} (PI), Ursula Jongebloed (co-PI). Total grant: \$7,000.

\item[\textbf{2023}] COLDEX ECR Grant. Detailed layer analysis of oldest ice. Liam Kirkpatrick (PI), \textbf{Jacob Chalif} (co-PI). Total grant: \$5,000.
\end{enumerate}

